import{_ as g,l as e,o as r,b as n,d as i,m as t,q as l,j as a,f as d}from"./chunks/framework.Tf23FRXt.js";const u="/assets/HUDnobattle.JexvNtNc.jpg",_="/assets/HUDinbattle.DdA6r6oH.jpg",v="/assets/9c1e76becd9f53ccd5388a977b9c265e91cdda.3X7CJLzz.jpg",m="/assets/1d595cef730a258b41095c4f854e7b730c7cf0.BaR_ry8q.jpg",b="/assets/09bed1d9dcf22561a86983fab3100f9bc42f77.YTRESDI1.jpg",h="/assets/8b80777c9cd0880e725d141d7bf83b200070f3.KSVBv16S.jpg",f="/assets/fa93a8460eeb428edf6318bf99dc67cf37856b.C-1VT8H3.jpg",x="/assets/979887d6c59570e6ad43d85b3c09acc777c338.C9iXBJHJ.jpg",T="/assets/sample1.DPx_vqbq.jpg",w="/assets/sample7.DQAGy5Cb.jpg",S="/assets/sample8.CFyYCgn8.jpg",C="/assets/sample6.B06o0ixA.jpg",j="/assets/sample5.vQuhdMp0.jpg",P="/assets/sample3.Dp1Tu_Fo.jpg",y="/assets/sample2.qXJPAcWU.jpg",A="/assets/sample4.DUSDLvV8.jpg",k="/assets/5d5960117e257caeb22e9182c78975ca3d560a.DwiR_pgU.jpg",z="/assets/ca1bf828f8b4db1f3b54c29633ea45a7a525bf.m7UM3sPT.jpg",D="/assets/e77230339f304d72673828a4238ccd3aa9e43e.CXY56IFl.jpg",V="/assets/f98baa7d85d72f011c97e450c628daee0d7bb8.C2Sff2T3.jpg",B="/assets/b765137d958dfe981606680fe321730ff023c4.r9zl61L_.jpg",O=JSON.parse('{"title":"界面指南","description":"","frontmatter":{},"headers":[{"level":2,"title":"界面介绍","slug":"界面介绍","link":"#界面介绍","children":[{"level":3,"title":"非战斗时","slug":"非战斗时","link":"#非战斗时","children":[]},{"level":3,"title":"战斗时","slug":"战斗时","link":"#战斗时","children":[]},{"level":3,"title":"名牌","slug":"名牌","link":"#名牌","children":[]},{"level":3,"title":"Q: 为什么敌人名字前面的图标不一样？","slug":"q-为什么敌人名字前面的图标不一样","link":"#q-为什么敌人名字前面的图标不一样","children":[]}]},{"level":2,"title":"改变界面部件的布局","slug":"改变界面部件的布局","link":"#改变界面部件的布局","children":[]}],"relativePath":"ui/how.htm.md","filePath":"ui/how.md","lastUpdated":1791098838000}'),N={name:"ui/how.htm.md"},I={class:"guide"},q={class:"guide col grow"};function E(R,s,F,U,H,J){const p=e("FloatTOC"),o=e("SegmentText"),c=e("CollapseText");return r(),n("div",null,[s[6]||(s[6]=i("h1",{id:"界面指南",tabindex:"-1"},"界面指南",-1)),t(p),s[7]||(s[7]=l('<p>FF14 的界面展示了大量信息，同时可以根据玩家的习惯自由定制。下面会介绍 FF14 游戏的界面阅读与修改的方法，如果你是第一次玩这类游戏，推荐你完整阅读下面的介绍；如果你已经是一位经验丰富的游戏玩家，也可以直接调整一下<a href="/ui/how.htm">让战斗更方便的设置</a>，然后直接阅读其他感兴趣的部分，或者直接在游戏中体验学习。</p><blockquote><ul><li><a href="/ui/hotbar.htm">如何设置技能 / 快捷栏</a></li><li><a href="/ui/config.htm">如何设置游戏</a></li><li><a href="/ui/battle.htm">让战斗更方便的设置</a></li></ul></blockquote><h2 id="界面介绍" tabindex="-1">界面介绍</h2><p>游戏界面包含了很多个界面窗口，它们都可以根据你的使用习惯和操作方法调整尺寸、位置、布局等等。一边进行冒险，一边调整觉得不舒服的地方吧！</p><p>虽然重新调整 UI 看起来有些吓人，但是即使是很小的调整也会让你体验游戏的方式有所不同。试着先从小的调整开始，朝着更大的方向进行。</p><h3 id="非战斗时" tabindex="-1">非战斗时</h3><div class="guide"><div class="guide col sticky"><p><img src="'+u+'" alt="" loading="lazy"></p></div><div class="guide col grow"><h4 id="主线向导" tabindex="-1">主线向导</h4><p>根据玩家的游戏主线进度，提示玩家接下来要去往的地方。<br>如果忘了自己要去哪里，就点一下向导上的任务名，然后过去看看吧。</p><h4 id="日志窗口" tabindex="-1">日志窗口</h4><p>这里会显示聊天的内容，战斗日志，还有游戏内广播等等。如果日志太多了读起来很痛苦，可以点右下角的 [齿轮] 按钮过滤一下。</p><p>另外点 <code>[+]</code> 的话，还可以添加一个窗口，在这个窗口里只保留自己想见到的信息，读起来就更轻松了。一定要尝试一下哦。</p><h4 id="热键栏" tabindex="-1">热键栏</h4><p>在热键栏上放上技能、道具之类的，就可以直接点击热键就用。热键的布局也可以根据自己的喜好定制！而且热键本身也可以自由更换。</p><p>手柄使用的热键栏为十字热键栏，可以通过 <code>LT</code> 、 <code>RT</code> （PS4/PS5 手柄为 <code>L2</code> 、 <code>R2</code> ）快速切换热键栏。</p><p><a href="/ui/hotbar.htm">点我查看热键栏与热键介绍</a>。</p><h4 id="角色参数" tabindex="-1">角色参数</h4><p>这里显示角色的基本参数、等级、经验值、休息奖励等信息。</p><p>休息奖励是指你在城市或者其他休息区挂机或者下线的时候，自动累积的经验值奖励。所以要下线的时候，记得找个城市或者休息区再下线哦！</p><h4 id="导向地图" tabindex="-1">导向地图</h4><p>这里显示角色周边情况的迷你地图。点击这个小地图，还可以打开地区地图。</p><p>只要你去过的地图就会自动记录。不断前往未知的地方，完成地图的记录吧！四处移动的同时也不要忘了与以太之光进行共鸣哦！</p><h4 id="目的列表" tabindex="-1">目的列表</h4><p>这里显示了接受的任务、理符的目的地，以及要完成它们所需的行动步骤。</p><p>点击任务的名字就会弹出目的地所在的地图，立刻动身前往目的地吧。完成蓝字所显示的要求并向 NPC 报告，就可以完成任务了。</p><h4 id="背包缩略图" tabindex="-1">背包缩略图</h4><p>背包空间的使用情况，现在装备的情况都可以从这里一目了然。点击这个缩略图的话，就可以跳转到角色信息或者背包中直接确认。</p><h4 id="快捷指令" tabindex="-1">快捷指令</h4><p>游戏中的菜单，在本站中基本以 “菜单” 称呼。点击按钮的话会显示相应的详细信息。</p><p>手柄玩家没有 [快捷指令]，可以按 <code>START</code> 键（PS4 和 PS5 手柄为 <code>OPTION</code> 键）打开指令菜单。</p><h4 id="所持金币" tabindex="-1">所持金币</h4><p>角色所持有的金币数量。</p><p>使用鼠标左键单击，会弹出货币窗口，窗口中会显示军票、工票、金碟币等等其他类型货币的持有数量。</p><p>使用鼠标右键单击，会快速切换显示预置的最多 5 种货币的种类和数量；切换的货币类型可以在货币窗口中进行设置。</p></div></div><h3 id="战斗时" tabindex="-1">战斗时</h3>',8)),i("div",I,[s[4]||(s[4]=i("div",{class:"guide col sticky"},[i("p",null,[i("img",{src:_,alt:"",loading:"lazy"})])],-1)),i("div",q,[s[1]||(s[1]=l('<h4 id="小队列表" tabindex="-1">小队列表</h4><p>包括自己在内的小队成员的列表。<br>在战斗中也会显示仇恨顺序、Buff/Debuff（强化状态 / 弱化状态）的信息。点击小队成员，也可以直接选中目标成员。</p><p>※在默认设定中，单人不组队的话是不会显示小队列表的。</p><h4 id="敌对列表" tabindex="-1">敌对列表</h4><p>这里显示战斗中的敌人，以及它们的仇恨情况。 <br>仇恨图标是红色话，就会被敌人攻击，要注意哦。</p><p><a href="/ui/battle.htm">什么是仇恨？如何分辨仇恨？</a></p><h4 id="目标-目标情报" tabindex="-1">目标 / 目标情报</h4><p>自己选中的目标、物体的信息。目标情报右边，会显示目标的目标。</p><h4 id="焦点目标情报" tabindex="-1">焦点目标情报</h4><p>这里显示自己设为焦点的目标情报。 一般来说，只有选择了目标之后，才会显示目标信息，但是如果将其设为焦点的话，就可以在屏幕上固定显示某一个目标的信息了，非常方便。一定要好好利用这个功能。</p>',10)),t(o,{className:"grey"},{default:a(()=>[...s[0]||(s[0]=[i("p",null,[i("strong",null,"设置焦点目标的方法")],-1),i("p",null,[d("①选中想要设为焦点的角色 / 敌人 "),i("br"),d("②鼠标右键（手柄为 "),i("code",null,"X"),d(" 或 "),i("code",null,"□"),d(" 键）从子命令中选择 “焦点目标”"),i("br"),d("③焦点目标的情报就会固定显示出来了")],-1)])]),_:1}),s[2]||(s[2]=i("h4",{id:"咏唱栏",tabindex:"-1"},"咏唱栏",-1)),s[3]||(s[3]=i("p",null,"当使用需要咏唱时间的技能时就会出现，会显示到放出技能为止所剩的时间。",-1))])]),s[8]||(s[8]=l('<h3 id="名牌" tabindex="-1">名牌</h3><p>敌人的名牌会根据目标，以及目标的交战状态而改变颜色。</p><div class="guide cols2"><div class="guide col"><p><img src="'+v+'" alt="" loading="lazy"></p></div><div class="guide col grow"><p>没有在战斗，闲逛状态的敌人</p></div></div><div class="guide cols2"><div class="guide col"><p><img src="'+m+'" alt="" loading="lazy"></p></div><div class="guide col grow"><p>自己搭档或小队成员率先进攻，正在战斗中的敌人</p></div></div><div class="guide cols2"><div class="guide col"><p><img src="'+b+'" alt="" loading="lazy"></p></div><div class="guide col grow"><p>主动攻击型的敌人，正在进行攻击，或者是连锁中的敌人</p></div></div><div class="guide cols2"><div class="guide col"><p><img src="'+h+'" alt="" loading="lazy"></p></div><div class="guide col grow"><p>自己搭档或小队成员以外的人率先进攻，正在战斗中的敌人</p></div></div><h3 id="q-为什么敌人名字前面的图标不一样" tabindex="-1">Q: 为什么敌人名字前面的图标不一样？</h3><div class="guide cols2"><div class="guide col"><p><img src="'+f+'" alt="" loading="lazy"><br><img src="'+x+'" alt="" loading="lazy"></p></div><div class="guide col grow"><p>敌人名牌左边的图标，表示对方是否是主动攻击型的敌人。图标的形状表示对方的种类、强弱。</p><p><strong>①蓝色的图标</strong><br> 就算靠近也不会主动进攻，是被动型的敌人。</p><p><strong>②红色图标</strong><br> 靠近的话就会主动袭击过来，是主动型的敌人，要注意哦。<br> ※提高自身等级之后，对方就不会再主动进攻了。</p><p>另外，敌方名牌根据临危受命，或特殊副本内容不同，而有专门的图标表示。具体信息可以看<a href="https://ff14.huijiwiki.com/wiki/%E6%95%8C%E4%BA%BA%E7%B1%BB%E5%9E%8B" target="_blank" rel="noreferrer">这里</a>。</p></div></div><h2 id="改变界面部件的布局" tabindex="-1">改变界面部件的布局</h2><p>所有界面部件的布局，都可以从快捷指令 &gt; 系统 &gt; 界面设置中变更。</p><p>首先从调整位置、大小，这些比较简单上手的部分开始吧。</p><p><a href="/ui/battle.htm">我是高清屏幕，UI 特别小怎么办？</a></p>',12)),t(c,{summary:"没有灵感，想看看大家是怎么摆的！"},{default:a(()=>[...s[5]||(s[5]=[i("div",{class:"guide cols3"},[i("div",{class:"guide col figcap"},[i("img",{src:T,width:"350px"}),i("p",null,"图片来自抹茶群热心网友")]),i("div",{class:"guide col figcap"},[i("img",{src:w,width:"350px"}),i("p",null,"图片来自抹茶群热心网友")]),i("div",{class:"guide col figcap"},[i("img",{src:S,width:"350px"}),i("p",null,"图片来自红宝石兽")])],-1),i("div",{class:"guide cols3"},[i("div",{class:"guide col figcap"},[i("img",{src:C,width:"350px"}),i("p",null,"【PVP】图片来自艾尼卡")]),i("div",{class:"guide col figcap"},[i("img",{src:j,width:"350px"}),i("p",null,"【手柄】图片来自抹茶群热心网友")]),i("div",{class:"guide col figcap"},[i("img",{src:P,width:"350px"}),i("p",null,"图片来自宏学杂技学家")])],-1),i("div",{class:"guide cols2"},[i("div",{class:"guide col figcap"},[i("img",{src:y,width:"450px"}),i("p",null,"【带鱼屏】图片来自 Wiki 群热心网友")]),i("div",{class:"guide col figcap"},[i("img",{src:A,width:"250px"}),i("p",null,"【小屏】图片来自抹茶群热心网友")])],-1)])]),_:1}),s[9]||(s[9]=l('<h4 id="_1-快捷指令-系统中选择-界面设置-。" tabindex="-1">① 快捷指令 &gt; 系统中选择 “界面设置”。</h4><div class="guide cols2"><div class="guide col"><p><img src="'+k+'" alt="" loading="lazy"></p></div><div class="guide col grow"><p>快捷指令 &gt; 系统中选择 “界面设置”。<br> ※游戏界面会变成 “界面设置模式”，此时就可以改变界面布局和设置了。</p></div></div><h4 id="_2-选中想要改变的界面窗口-调整布局。" tabindex="-1">② 选中想要改变的界面窗口，调整布局。</h4><div class="guide cols2"><div class="guide col"><p><img src="'+z+'" alt="" loading="lazy"></p></div><div class="guide col grow"><p><strong>选择界面部件的方法</strong><br> 在界面设置中，可以从 “当前窗口” 的下拉菜单中选择想要设置的界面部件。<br> ※选中的界面部件边框会变为黄色。</p><p><strong>移动位置</strong><br> 选中界面部件之后，就可以拖拽它到任意地方。</p></div></div><div class="guide cols2"><div class="guide col"><p><img src="'+D+'" alt="" loading="lazy"></p></div><div class="guide col grow"><p><strong>改变尺寸和透明度</strong><br> 在界面设置中，点击当前窗口右边的齿轮图标（当前窗口设置），可以修改窗口尺寸和透明度。选中窗口按 <code>Ctrl</code> + <code>Home</code> 快捷键，也可以改变窗口尺寸。</p><p><strong>显示 / 隐藏切换</strong><br> 右键界面部件，就可以切换显示 / 隐藏部件。<br> ※隐藏的界面部件的名字会变为紫色。</p></div></div><div class="guide cols2"><div class="guide col"><p><img src="'+V+'" alt="" loading="lazy"></p></div><div class="guide col grow"><p><strong>复制布局</strong><br> 点击界面设置右上角的齿轮图标（界面设置储存功能），选中想要复制的目标编号，然后点击确认按钮。。</p></div></div><h4 id="_3-设置全都保存好了" tabindex="-1">③ 设置全都保存好了！</h4><div class="guide cols2"><div class="guide col"><p><img src="'+B+'" alt="" loading="lazy"></p></div><div class="guide col grow"><p>如果调整好了界面设置，点击保存按钮就搞定了。快点去试试吧。</p><p>※布局之外的界面设置，可以在角色设置中的界面设置里找到。</p></div></div><blockquote><ul><li><a href="/ui/hotbar.htm">如何设置技能 / 快捷栏</a></li><li><a href="/ui/config.htm">如何设置游戏</a></li><li><a href="/ui/battle.htm">让战斗更方便的设置</a></li></ul></blockquote>',9))])}const X=g(N,[["render",E]]);export{O as __pageData,X as default};
